window.I18N={"en": {"k1": "Yes", "k2": "on 12", "k3": "Measure 12 funds safe crosswalks, slower school zones and repaired sidewalks. Vote Yes on February 9.", "k4": "Sign the pledge", "k5": "See what it does", "k6": "neighbors have signed the pledge", "k7": "Example data. Not a real count.", "k8": "Crosswalks", "k9": "Marked, lit crossings at the busiest school and transit corners, with signals where traffic is heaviest.", "k10": "Slower school zones", "k11": "Speed limits drop to 20 mph within a block of every school, backed by speed humps and clear signs.", "k12": "Sidewalks that work", "k13": "Cracked and missing sidewalk on routes to school gets rebuilt, worst blocks first.", "k14": "What your Yes pays for", "k15": "See how a corner changes", "k16": "school-area crossings upgraded in the plan", "k17": "blocks of sidewalk rebuilt on routes to school", "k18": "years of funding, then voters decide whether to renew", "k19": "Example figures for illustration.", "k20": "Add your name", "k21": "Pledges show city hall that neighbors are watching. It takes ten seconds.", "k22": "Full name", "k23": "Email", "k24": "ZIP code", "k25": "I plan to vote Yes on Measure 12.", "k26": "We send election reminders only. This demo sends nothing anywhere.", "k27": "You are in.", "k28": "Your pledge is counted. Tell five neighbors.", "k29": "Get your share kit", "k30": "Donate", "k31": "Who is backing it", "k32": "Port Ellery Parents Network", "k33": "Parents from every school zone in the city, fictional for this concept.", "k34": "Port Ellery Teachers Council", "k35": "Harbor Street Merchants Association", "k36": "Dockside Workers Union", "k37": "See all 20 endorsements", "k38": "Nov", "k39": "Sat", "k40": "Delaney Elementary front steps", "k41": "Delaney Street walk audit", "k42": "Tue", "k43": "Eastside Library, meeting room B", "k44": "Tuesday phone bank", "k45": "Dec", "k46": "Alder Row Cafe, Harbor Street", "k47": "Bayview door knock", "k48": "Next up near you", "k49": "See all events", "k50": "Vote Yes February 9", "k51": "Yes on 12 | Safe streets for Port Ellery", "k52": "Vote Yes on Measure 12 to fund safe crosswalks, slower school zones and sidewalk repair in Port Ellery. Fictional concept site.", "k53": "Skip to content", "k54": "What it does", "k55": "Endorsements", "k56": "FAQ", "k57": "Events", "k58": "Pledge", "k59": "Yes on 12, home", "k60": "Yes on 12", "k61": "Main", "k62": "Language", "k63": "Toggle dark mode", "k64": "Menu", "k65": "Safe crosswalks, slower school zones and sidewalks that work. Port Ellery, special election February 9, 2027.", "k66": "Privacy", "k67": "Accessibility", "k68": "Paid for by Safe Streets Coalition, Yes on 12 Committee. Not authorized by any candidate or candidate committee.", "k69": "Concept design by DBF Designs. Fictional ballot measure for illustration. Any resemblance to real people or organizations is coincidental.", "k70": "Photography: Pexels.", "k71": "Top-down diagram of a street intersection. A school bus approaches a crossing. Use the controls to add crosswalks, a signal and curb extensions.", "k72": "Preset", "k73": "Today", "k74": "With Measure 12", "k75": "Marked crosswalks", "k76": "Pedestrian signal", "k77": "Curb extensions", "k78": "Crossing distance", "k79": "Typical speed", "k80": "Relative risk index", "k81": "Send a bus through", "k82": "Example data for illustration. The risk index starts at 100 for today's corner.", "k83": "Try one corner", "k84": "Switch each fix on, then send a school bus through. The numbers are example data.", "k85": "What it is", "k86": "Measure 12 is a city ballot question. If most voters say Yes, Port Ellery adds a 0.12 percent sales tax for eight years and spends it only on street safety.", "k87": "What it costs", "k88": "About $14 a year for a typical household (example figure). Property tax bills do not change.", "k89": "What it builds", "k90": "Marked and signaled crossings, 20 mph school zones with speed humps, and rebuilt sidewalk on routes to school.", "k91": "Who checks the work", "k92": "A citizens' oversight panel reviews every project and publishes a yearly report. Each project appears on a public map.", "k93": "What it does not do", "k94": "It cannot be spent on anything else. Unspent money stays in the street safety fund.", "k95": "In plain words", "k96": "Where each dollar goes", "k97": "Example allocation. The oversight panel can shift up to 5 percent between lines each year.", "k98": "Allocation: crosswalks and signals 41.0 percent, school-zone slowdowns 34.5 percent, sidewalk repair 24.5 percent.", "k99": "Crosswalks and signals", "k100": "41.0 percent (example)", "k101": "School-zone slowdowns", "k102": "34.5 percent (example)", "k103": "Sidewalk repair", "k104": "24.5 percent (example)", "k105": "After a Yes vote", "k106": "Feb 9, 2027", "k107": "Voters decide on Measure 12.", "k108": "Spring 2027", "k109": "The oversight panel is seated and the public map goes live.", "k110": "Summer 2027", "k111": "The first 12 school crossings are built.", "k112": "Every year", "k113": "A public report lists every project and dollar.", "k114": "Ready to vote Yes?", "k115": "Read the myths and facts", "k116": "What Measure 12 does", "k117": "A plain-language guide to what it builds, what it costs and who checks the work.", "k118": "What Measure 12 does | Yes on 12", "k119": "A plain-language guide to what Measure 12 builds, what it costs and who checks the work, with an interactive street corner.", "k120": "All", "k121": "Parents", "k122": "Teachers", "k123": "Business", "k124": "Faith", "k125": "Labor", "k126": "Every parent we survey has a story about a near miss on the walk to school. This measure answers it.", "k127": "Delaney Elementary PTA", "k128": "Our crossing guard counts more than 140 kids across Delaney Street each morning. They deserve a signal.", "k129": "Eastside Stroller Club", "k130": "We push strollers over cracked sidewalks every day. Fixing them helps parents, grandparents and anyone on wheels.", "k131": "Hollis Park Family Association", "k132": "Our park sits beside a four-lane road with no crossing. A marked crossing and a slower speed limit are overdue.", "k133": "Marlowe Street Walking School Bus", "k134": "Twenty-two kids walk together every morning. Safer corners let us invite more families.", "k135": "Students cannot learn if they are late, frightened or hurt. Safe routes are part of the school day.", "k136": "Bayview Middle School Faculty Senate", "k137": "We watch the corner outside our doors every afternoon. We know what it needs.", "k138": "Cedar Lane Elementary Staff", "k139": "Our front office keeps a list of close calls. Measure 12 gives us a way to shorten it.", "k140": "Port Ellery Retired Educators", "k141": "We taught thousands of children on these streets. We want the next generation to cross them safely.", "k142": "Customers walk to our shops. Safer crossings and smoother sidewalks bring more of them through the door.", "k143": "Tidewater Bakery Collective", "k144": "Our early shift walks to work in the dark. Better lighting and crossings matter to them.", "k145": "Eastside Small Business Alliance", "k146": "Fixing streets once costs less than repairing them forever. We support a plan with a public audit.", "k147": "Alder Row Cafe Owners", "k148": "Families stop for breakfast on the way to school. We want every one of them to arrive safely.", "k149": "Wren Hill Interfaith Council", "k150": "Our congregations share one concern: the children who cross Wren Hill Road. We ask for a Yes vote.", "k151": "Amity Street Congregation", "k152": "Many of our members walk with canes and walkers. Level sidewalks are a matter of dignity.", "k153": "Bayview Temple Social Action Committee", "k154": "Caring for neighbors includes caring for the street outside. We are knocking doors for Measure 12.", "k155": "Saint Odile Parish Council", "k156": "After Sunday services, families cross a busy road with no signal. A Yes vote changes that.", "k157": "Our members build and repair this city. They also walk its streets to work and want them safe.", "k158": "Building Trades Council of Port Ellery", "k159": "Measure 12 means steady local work on crosswalks and sidewalks, done by trained crews at fair wages.", "k160": "Municipal Crossing Guards Association", "k161": "We stand in the road every school day. We know where it fails and we are asking for a fix.", "k162": "Filter by type", "k163": "Showing", "k164": "of", "k165": "No endorsements in this group yet.", "k166": "Painted lines would help. Signals would help more.", "k167": "Delaney Elementary PTA, fictional organization", "k168": "Endorse Measure 12", "k169": "Organizations of any size can add their name. We confirm by email before listing.", "k170": "Organization name", "k171": "Contact name", "k172": "Organization type", "k173": "Choose one", "k174": "Submit endorsement", "k175": "Thank you.", "k176": "We will email you to confirm. Nothing was sent in this demo.", "k177": "Add your name too", "k178": "Who backs Measure 12", "k179": "Parents, teachers, shop owners, faith communities and workers. All fictional organizations for this concept.", "k180": "Endorsements | Yes on 12", "k181": "Parents, teachers, business owners, faith communities and labor groups backing Measure 12. All organizations are fictional.", "k182": "Myth", "k183": "It raises my property taxes.", "k184": "Fact", "k185": "It does not. Measure 12 is a 0.12 percent sales tax for eight years. Property tax bills do not change.", "k186": "Crosswalk paint does not stop crashes.", "k187": "Paint alone helps little. That is why the measure pairs crossings with signals, curb extensions and slower speeds at the same corners.", "k188": "The money will vanish into the general fund.", "k189": "Revenue goes into a separate street safety fund. By law it cannot be spent on anything else.", "k190": "Only school neighborhoods benefit.", "k191": "Sidewalks and signals serve seniors, wheelchair users and anyone walking to the bus. Projects are ranked by crash history, not by ZIP code.", "k192": "Lower speed limits just cause traffic.", "k193": "School zones drop to 20 mph only within a block of each school during arrival and dismissal. Trips across town barely change.", "k194": "Nobody will watch how it is spent.", "k195": "A citizens' panel reviews every project and publishes a yearly report. An independent audit is required every two years.", "k196": "The city can already afford this.", "k197": "Today's budget covers about a tenth of the city's own repair backlog (example figure). Measure 12 funds the rest.", "k198": "It will take decades.", "k199": "The first 12 school crossings are scheduled within six months of passage, and the full plan finishes in eight years.", "k200": "Ask us something", "k201": "Your question", "k202": "Send question", "k203": "A volunteer will reply by email. Nothing was sent in this demo.", "k204": "Straight answers", "k205": "Short answers to what we hear most at the door.", "k206": "The measure at a glance", "k207": "Election day", "k208": "Sales tax", "k209": "0.12%", "k210": "Duration", "k211": "8 years", "k212": "Oversight", "k213": "Citizens' panel", "k214": "Facts beat myths", "k215": "Myth or fact", "k216": "What people ask about Measure 12, answered plainly.", "k217": "Myths and facts | Yes on 12", "k218": "Short, honest answers about Measure 12: cost, oversight, school zones and timing. Myth versus fact.", "k219": "Canvass", "k220": "Phone bank", "k221": "Town hall", "k222": "Walk audit", "k223": "House meeting", "k224": "RSVP", "k225": "Add to calendar", "k226": "Walk the worst crossings with parents and city engineers, and log what you see.", "k227": "Call voters from a script, with pizza and a trainer on hand. No experience needed.", "k228": "Knock on doors in pairs along the school routes. Maps and water provided.", "k229": "Wed", "k230": "Port Ellery Central Library auditorium", "k231": "Ask the coalition and the city traffic engineer your questions. Interpreters on site.", "k232": "Measure 12 town hall", "k233": "Hollis Park pavilion", "k234": "Share the plan with neighbors and sign up yard sign hosts along the main blocks.", "k235": "Hollis Park block canvass", "k236": "Same room, same pizza, new call list. Bring a friend and double the calls.", "k237": "Jan", "k238": "Marlowe Street Walking School Bus meeting point", "k239": "Time the signals, count the cars and mark the missing curb ramps.", "k240": "Marlowe Street walk audit", "k241": "Thu", "k242": "Bayview Middle School cafeteria", "k243": "Teachers and parents talk about the walk to school and what a Yes vote changes.", "k244": "Parents and teachers town hall", "k245": "Feb", "k246": "Union Hall, Dockside", "k247": "Pick up a packet and a route. Every shift is two hours or longer, your choice.", "k248": "Final weekend canvass kickoff", "k249": "Sun", "k250": "Remind supporters that the vote is Tuesday and where to find their polling place.", "k251": "Get out the vote phone bank", "k252": "Filter by event type", "k253": "No house meetings are scheduled yet.", "k254": "Want to host one? Sign up for a shift below and we will help you plan it.", "k255": "Close", "k256": "Guests including you", "k257": "Confirm RSVP", "k258": "You are on the list.", "k259": "A reminder goes out the day before. Nothing was sent in this demo.", "k260": "Nov 21: Delaney Street walk audit", "k261": "Nov 24: Tuesday phone bank", "k262": "Dec 5: Bayview door knock", "k263": "Dec 9: Measure 12 town hall", "k264": "Dec 12: Hollis Park block canvass", "k265": "Dec 15: Tuesday phone bank", "k266": "Jan 9: Marlowe Street walk audit", "k267": "Jan 14: Parents and teachers town hall", "k268": "Feb 6: Final weekend canvass kickoff", "k269": "Feb 7: Get out the vote phone bank", "k270": "Sign up to volunteer", "k271": "Pick a shift and we will send details. Rides and childcare can be arranged.", "k272": "Shift", "k273": "Choose a shift", "k274": "Phone", "k275": "optional", "k276": "Sign up for shift", "k277": "You are signed up.", "k278": "A coordinator will confirm by email. Nothing was sent in this demo.", "k279": "Can't make it? Donate", "k280": "Show up for one shift. Walk a corner, make a call or ask the engineer a question.", "k281": "Events | Yes on 12", "k282": "Canvasses, phone banks, town halls and walk audits for Measure 12. RSVP and add events to your calendar.", "k283": "Add your name, then share it with five people. That is how Measure 12 wins.", "k284": "Your share kit", "k285": "Text a neighbor", "k286": "Hi, it's me. I pledged to vote Yes on 12 on February 9. It pays for safe crosswalks near our kids' schools. Can I count on you too?", "k287": "Copy", "k288": "Quick reminder: Measure 12 is on the ballot February 9. Yes means safer crosswalks and sidewalks near every school.", "k289": "Free Saturday? We are walking the worst crossings near Delaney Elementary at 10. Come see why 12 matters.", "k290": "Post it", "k291": "Vote Yes on 12 on February 9. Safe crosswalks. Slower school zones. Sidewalks that work. #YesOn12", "k292": "Every school morning, kids in Port Ellery cross streets with no signal and no marked crossing. Measure 12 changes that. I pledged Yes. Will you?", "k293": "I just signed the Yes on 12 pledge. It takes ten seconds and helps kids walk to school safely. #YesOn12", "k294": "Copy link", "k295": "Share", "k296": "Request a yard sign", "k297": "Street address", "k298": "Sign type", "k299": "Yard sign, 24 by 18 inches", "k300": "Window poster, 11 by 17 inches", "k301": "Request sign", "k302": "Request received.", "k303": "A volunteer will deliver it within a week. Nothing was sent in this demo.", "k304": "Signs need stakes. So do campaigns.", "k305": "Pledge your vote", "k306": "Sign the pledge, then pass it on.", "k307": "Pledge your vote | Yes on 12", "k308": "Sign the Yes on 12 pledge, copy texts and posts to share, and request a yard sign. Everything runs in your browser.", "k309": "Amount", "k310": "Your info", "k311": "Demo payment", "k312": "Done", "k313": "You give", "k314": "one time", "k315": "every month", "k316": "Choose an amount", "k317": "Amount in US dollars", "k318": "Custom amount in dollars", "k319": "Other", "k320": "Frequency", "k321": "One time", "k322": "Monthly", "k323": "Continue", "k324": "First name", "k325": "Last name", "k326": "Your information", "k327": "Employer", "k328": "Occupation", "k329": "I am a US citizen or permanent resident and this is my own money.", "k330": "Back", "k331": "Review your gift", "k332": "Demo: no real payment is taken. No card details are collected on this site.", "k333": "Name", "k334": "A real campaign would connect a payment processor here.", "k335": "Confirm demo donation", "k336": "This was a demo, so no money moved. A real receipt would arrive by email.", "k337": "Demo confirmation", "k338": "Nothing was sent or stored.", "k339": "Start over", "k340": "Progress", "k341": "What a gift does", "k342": "prints 60 yard signs (example)", "k343": "covers a month of phone bank pizza and training (example)", "k344": "funds a mailer to 2,400 homes (example)", "k345": "Other ways to help", "k346": "Volunteer", "k347": "Take one two-hour shift. Walk a corner, knock a few doors or make calls.", "k348": "See events", "k349": "Pledge", "k350": "Add your name and send the share kit to five neighbors.", "k351": "Contribution rules", "k352": "Contributions are not tax deductible. You must give from your own funds and be eligible to give under local law. Corporate gifts may be restricted. This concept site takes no real payments.", "k353": "Give what you can. Gifts pay for yard signs, mailers and volunteer training.", "k354": "Donate | Yes on 12", "k355": "Donate to the Yes on 12 campaign. This is a demo flow: no real payment is taken and nothing is stored.", "k356": "What we collect", "k357": "Nothing. Forms on this site show how a real campaign form would behave, then discard what you entered.", "k358": "What stays in your browser", "k359": "Your language and light or dark choice, and the example pledge counter, are saved in your browser storage so the site remembers them. You can clear them in your browser settings.", "k360": "Third-party files", "k361": "Fonts load from Google Fonts and icons load from unpkg. Those services may receive your IP address when they serve the files.", "k362": "A real campaign", "k363": "A real version of this site would publish a full policy covering email, text messages, donations and data sharing.", "k364": "This is a concept site. Nothing you type leaves your browser.", "k365": "Privacy | Yes on 12", "k366": "How this concept site handles your information: it does not send or collect anything.", "k367": "Our target", "k368": "We design to WCAG 2.2 level AA: readable contrast in light and dark modes, visible keyboard focus and buttons at least 44 pixels tall.", "k369": "What is built in", "k370": "Skip link, labeled forms with errors below each field, keyboard-operable menus, dialogs and accordions, and full English and Spanish text.", "k371": "Motion respects your system setting. With reduced motion on, the stripes, counter and diagram appear without animation.", "k372": "Tell us about a barrier", "k373": "This is a concept site, so there is no live inbox. A real campaign would list an email address and phone number here and reply within two business days.", "k374": "Everyone should be able to read about, pledge for and vote on Measure 12.", "k375": "Accessibility | Yes on 12", "k376": "Accessibility commitments and features for the Yes on 12 concept site.", "js_counted": "Pledge counted. You are number", "js_copy": "Copy", "js_copied": "Copied", "js_once": "One time", "js_monthly": "Monthly", "js_e_req": "This field is required.", "js_e_email": "Enter a valid email address.", "js_e_zip": "Enter a 5-digit ZIP code.", "js_e_amount": "Choose or enter an amount.", "js_e_cap": "Demo gifts are capped at $5,000.", "js_ics_desc": "Yes on 12 volunteer event. Fictional concept.", "js_v_none": "No marked crossing: the bus keeps going and walkers wait for a gap.", "js_v_cw": "A marked crosswalk: the bus slows, but walkers still wait for a gap.", "js_v_sig": "With a signal: the bus stops at the line and the walker crosses."}, "es": {"k1": "Sí", "k2": "a la 12", "k3": "La Medida 12 financia cruces seguros, zonas escolares más lentas y aceras reparadas. Vota Sí el 9 de febrero.", "k4": "Firmar el compromiso", "k5": "Ver qué hace", "k6": "vecinos han firmado el compromiso", "k7": "Datos de ejemplo. No es un conteo real.", "k8": "Cruces", "k9": "Cruces marcados e iluminados en las esquinas más transitadas de escuelas y transporte, con semáforos donde el tráfico es mayor.", "k10": "Zonas escolares más lentas", "k11": "El límite baja a 20 mph a una cuadra de cada escuela, con topes y señales claras.", "k12": "Aceras que funcionan", "k13": "Las aceras rotas o faltantes en rutas escolares se reconstruyen, empezando por las peores cuadras.", "k14": "Lo que paga tu Sí", "k15": "Ver cómo cambia una esquina", "k16": "cruces escolares mejorados en el plan", "k17": "cuadras de acera reconstruidas en rutas escolares", "k18": "años de financiamiento; después los votantes deciden si lo renuevan", "k19": "Cifras de ejemplo para ilustración.", "k20": "Agrega tu nombre", "k21": "Los compromisos muestran al ayuntamiento que los vecinos están atentos. Toma diez segundos.", "k22": "Nombre completo", "k23": "Correo electrónico", "k24": "Código postal", "k25": "Pienso votar Sí en la Medida 12.", "k26": "Solo enviamos recordatorios electorales. Esta demostración no envía nada.", "k27": "Ya estás dentro.", "k28": "Tu compromiso cuenta. Cuéntaselo a cinco vecinos.", "k29": "Obtener tu kit para compartir", "k30": "Donar", "k31": "Quiénes lo respaldan", "k32": "Port Ellery Parents Network", "k33": "Padres de cada zona escolar de la ciudad, ficticios para este concepto.", "k34": "Consejo de Maestros de Port Ellery", "k35": "Asociación de Comerciantes de Harbor Street", "k36": "Sindicato de Trabajadores de Dockside", "k37": "Ver los 20 respaldos", "k38": "nov", "k39": "Sáb", "k40": "Escalinata de Delaney Elementary", "k41": "Recorrido de revisión en Delaney Street", "k42": "Mar", "k43": "Biblioteca Eastside, sala B", "k44": "Llamadas del martes", "k45": "dic", "k46": "Alder Row Cafe, Harbor Street", "k47": "Visitas casa por casa en Bayview", "k48": "Lo que sigue cerca de ti", "k49": "Ver todos los eventos", "k50": "Vota Sí el 9 de febrero", "k51": "Sí a la 12 | Calles seguras para Port Ellery", "k52": "Vota Sí en la Medida 12 para financiar cruces seguros, zonas escolares más lentas y reparación de aceras en Port Ellery. Sitio conceptual ficticio.", "k53": "Saltar al contenido", "k54": "Qué hace", "k55": "Respaldos", "k56": "Preguntas", "k57": "Eventos", "k58": "Compromiso", "k59": "Sí a la 12, inicio", "k60": "Sí a la 12", "k61": "Principal", "k62": "Idioma", "k63": "Cambiar modo oscuro", "k64": "Menú", "k65": "Cruces seguros, zonas escolares más lentas y aceras que funcionan. Port Ellery, elección especial el 9 de febrero de 2027.", "k66": "Privacidad", "k67": "Accesibilidad", "k68": "Pagado por Safe Streets Coalition, Comité Sí a la 12. No autorizado por ningún candidato ni comité de candidato.", "k69": "Diseño conceptual de DBF Designs. Medida electoral ficticia para ilustración. Cualquier parecido con personas u organizaciones reales es coincidencia.", "k70": "Fotografía: Pexels.", "k71": "Diagrama desde arriba de una intersección. Un autobús escolar se acerca a un cruce. Usa los controles para añadir cruces, un semáforo y extensiones de acera.", "k72": "Ajuste", "k73": "Hoy", "k74": "Con la Medida 12", "k75": "Cruces marcados", "k76": "Semáforo peatonal", "k77": "Extensiones de acera", "k78": "Distancia de cruce", "k79": "Velocidad típica", "k80": "Índice de riesgo relativo", "k81": "Enviar un autobús", "k82": "Datos de ejemplo para ilustración. El índice de riesgo parte de 100 para la esquina de hoy.", "k83": "Prueba una esquina", "k84": "Activa cada mejora y envía un autobús escolar. Los números son datos de ejemplo.", "k85": "Qué es", "k86": "La Medida 12 es una pregunta en la boleta municipal. Si la mayoría vota Sí, Port Ellery añade un impuesto a las ventas de 0.12 por ciento durante ocho años y lo gasta solo en seguridad vial.", "k87": "Cuánto cuesta", "k88": "Unos $14 al año para un hogar típico (cifra de ejemplo). Los impuestos a la propiedad no cambian.", "k89": "Qué construye", "k90": "Cruces marcados y con semáforo, zonas escolares de 20 mph con topes y aceras reconstruidas en rutas escolares.", "k91": "Quién revisa el trabajo", "k92": "Un panel ciudadano de supervisión revisa cada proyecto y publica un informe anual. Cada proyecto aparece en un mapa público.", "k93": "Qué no hace", "k94": "No se puede gastar en otra cosa. El dinero no gastado se queda en el fondo de seguridad vial.", "k95": "En palabras simples", "k96": "A dónde va cada dólar", "k97": "Distribución de ejemplo. El panel puede mover hasta 5 por ciento entre líneas cada año.", "k98": "Distribución: cruces y semáforos 41.0 por ciento, zonas escolares 34.5 por ciento, reparación de aceras 24.5 por ciento.", "k99": "Cruces y semáforos", "k100": "41.0 por ciento (ejemplo)", "k101": "Zonas escolares más lentas", "k102": "34.5 por ciento (ejemplo)", "k103": "Reparación de aceras", "k104": "24.5 por ciento (ejemplo)", "k105": "Después de un voto Sí", "k106": "9 feb 2027", "k107": "Los votantes deciden sobre la Medida 12.", "k108": "Primavera 2027", "k109": "Se instala el panel de supervisión y se publica el mapa.", "k110": "Verano 2027", "k111": "Se construyen los primeros 12 cruces escolares.", "k112": "Cada año", "k113": "Un informe público detalla cada proyecto y dólar.", "k114": "¿Listo para votar Sí?", "k115": "Leer mitos y hechos", "k116": "Lo que hace la Medida 12", "k117": "Una guía en lenguaje sencillo: qué construye, cuánto cuesta y quién revisa el trabajo.", "k118": "Qué hace la Medida 12 | Sí a la 12", "k119": "Una guía en lenguaje sencillo sobre lo que construye la Medida 12, cuánto cuesta y quién revisa el trabajo, con una esquina interactiva.", "k120": "Todos", "k121": "Padres", "k122": "Maestros", "k123": "Negocios", "k124": "Fe", "k125": "Sindicatos", "k126": "Todos los padres que encuestamos tienen una historia de un casi accidente camino a la escuela. Esta medida la responde.", "k127": "Asociación de Padres de Delaney Elementary", "k128": "Nuestro guardia de cruce acompaña a más de 140 niños cada mañana en Delaney Street. Merecen un semáforo.", "k129": "Club de Carriolas de Eastside", "k130": "Empujamos carriolas por aceras rotas todos los días. Arreglarlas ayuda a padres, abuelos y a cualquiera con ruedas.", "k131": "Asociación de Familias de Hollis Park", "k132": "Nuestro parque está junto a una avenida de cuatro carriles sin cruce. Un cruce marcado y un límite más bajo ya se hacían esperar.", "k133": "Autobús Escolar a Pie de Marlowe Street", "k134": "Veintidós niños caminan juntos cada mañana. Esquinas más seguras nos permiten invitar a más familias.", "k135": "Los estudiantes no aprenden si llegan tarde, asustados o heridos. Las rutas seguras son parte de la jornada escolar.", "k136": "Senado de Docentes de Bayview Middle School", "k137": "Vemos la esquina frente a nuestras puertas cada tarde. Sabemos lo que necesita.", "k138": "Personal de Cedar Lane Elementary", "k139": "Nuestra oficina lleva una lista de sustos. La Medida 12 nos da una forma de acortarla.", "k140": "Educadores Jubilados de Port Ellery", "k141": "Enseñamos a miles de niños en estas calles. Queremos que la próxima generación las cruce con seguridad.", "k142": "Los clientes caminan hasta nuestras tiendas. Cruces más seguros y aceras en buen estado traen más gente.", "k143": "Cooperativa de Panaderías Tidewater", "k144": "Nuestro turno temprano camina al trabajo de madrugada. Mejor iluminación y cruces les importan.", "k145": "Alianza de Pequeños Negocios de Eastside", "k146": "Arreglar las calles una vez cuesta menos que repararlas por siempre. Apoyamos un plan con auditoría pública.", "k147": "Dueños de Cafeterías de Alder Row", "k148": "Las familias desayunan camino a la escuela. Queremos que todas lleguen sanas y salvas.", "k149": "Consejo Interreligioso de Wren Hill", "k150": "Nuestras congregaciones comparten una preocupación: los niños que cruzan Wren Hill Road. Pedimos un voto Sí.", "k151": "Congregación de Amity Street", "k152": "Muchos de nuestros miembros caminan con bastón o andador. Las aceras parejas son cuestión de dignidad.", "k153": "Comité de Acción Social del Templo de Bayview", "k154": "Cuidar a los vecinos incluye cuidar la calle de afuera. Estamos tocando puertas por la Medida 12.", "k155": "Consejo Parroquial de Santa Odile", "k156": "Después de la misa, las familias cruzan una calle transitada sin semáforo. Un voto Sí lo cambia.", "k157": "Nuestros miembros construyen y reparan esta ciudad. También caminan sus calles al trabajo y las quieren seguras.", "k158": "Consejo de Oficios de la Construcción de Port Ellery", "k159": "La Medida 12 significa trabajo local constante en cruces y aceras, con cuadrillas capacitadas y salarios justos.", "k160": "Asociación de Guardias de Cruce Municipales", "k161": "Estamos en la calle cada día de clases. Sabemos dónde falla y pedimos una solución.", "k162": "Filtrar por tipo", "k163": "Mostrando", "k164": "de", "k165": "Aún no hay respaldos en este grupo.", "k166": "Las líneas pintadas ayudarían. Un semáforo ayudaría más.", "k167": "Asociación de Padres de Delaney Elementary, organización ficticia", "k168": "Respalda la Medida 12", "k169": "Organizaciones de cualquier tamaño pueden sumarse. Confirmamos por correo antes de publicar.", "k170": "Nombre de la organización", "k171": "Nombre de contacto", "k172": "Tipo de organización", "k173": "Elige uno", "k174": "Enviar respaldo", "k175": "Gracias.", "k176": "Te escribiremos para confirmar. En esta demostración no se envió nada.", "k177": "Suma también tu nombre", "k178": "Quiénes respaldan la Medida 12", "k179": "Padres, maestros, comerciantes, comunidades de fe y trabajadores. Todas son organizaciones ficticias para este concepto.", "k180": "Respaldos | Sí a la 12", "k181": "Padres, maestros, negocios, comunidades de fe y sindicatos que respaldan la Medida 12. Todas las organizaciones son ficticias.", "k182": "Mito", "k183": "Sube mis impuestos a la propiedad.", "k184": "Hecho", "k185": "No. La Medida 12 es un impuesto a las ventas de 0.12 por ciento durante ocho años. Los impuestos a la propiedad no cambian.", "k186": "La pintura de los cruces no evita choques.", "k187": "La pintura sola ayuda poco. Por eso la medida combina cruces con semáforos, extensiones de acera y menor velocidad en las mismas esquinas.", "k188": "El dinero se perderá en el fondo general.", "k189": "Los ingresos van a un fondo separado de seguridad vial. Por ley no se pueden gastar en otra cosa.", "k190": "Solo los barrios con escuelas se benefician.", "k191": "Las aceras y los semáforos sirven a personas mayores, usuarios de silla de ruedas y a quien camina al autobús. Los proyectos se ordenan por historial de choques, no por código postal.", "k192": "Menores límites de velocidad solo causan tráfico.", "k193": "Las zonas escolares bajan a 20 mph solo a una cuadra de cada escuela en horas de entrada y salida. Los viajes por la ciudad casi no cambian.", "k194": "Nadie vigilará cómo se gasta.", "k195": "Un panel ciudadano revisa cada proyecto y publica un informe anual. Se exige una auditoría independiente cada dos años.", "k196": "La ciudad ya puede pagar esto.", "k197": "El presupuesto actual cubre cerca de una décima parte del rezago de reparaciones de la ciudad (cifra de ejemplo). La Medida 12 financia el resto.", "k198": "Tardará décadas.", "k199": "Los primeros 12 cruces escolares están programados dentro de seis meses tras la aprobación y el plan completo termina en ocho años.", "k200": "Pregúntanos algo", "k201": "Tu pregunta", "k202": "Enviar pregunta", "k203": "Un voluntario responderá por correo. En esta demostración no se envió nada.", "k204": "Respuestas directas", "k205": "Respuestas breves a lo que más escuchamos en las puertas.", "k206": "La medida de un vistazo", "k207": "Día de elección", "k208": "Impuesto a las ventas", "k209": "0.12%", "k210": "Duración", "k211": "8 años", "k212": "Supervisión", "k213": "Panel ciudadano", "k214": "Los hechos vencen a los mitos", "k215": "Mito o hecho", "k216": "Lo que la gente pregunta sobre la Medida 12, respondido con claridad.", "k217": "Mitos y hechos | Sí a la 12", "k218": "Respuestas breves y honestas sobre la Medida 12: costo, supervisión, zonas escolares y plazos. Mito contra hecho.", "k219": "Visitas casa por casa", "k220": "Llamadas", "k221": "Asamblea pública", "k222": "Recorrido de revisión", "k223": "Reunión en casa", "k224": "Confirmar asistencia", "k225": "Añadir al calendario", "k226": "Camina los cruces más peligrosos con padres e ingenieros de la ciudad y anota lo que veas.", "k227": "Llama a votantes con un guión, con pizza y un instructor presente. No se necesita experiencia.", "k228": "Visita casas en parejas por las rutas escolares. Ofrecemos mapas y agua.", "k229": "Mié", "k230": "Auditorio de la Biblioteca Central de Port Ellery", "k231": "Haz tus preguntas a la coalición y al ingeniero de tránsito de la ciudad. Habrá intérpretes.", "k232": "Asamblea pública sobre la Medida 12", "k233": "Pabellón de Hollis Park", "k234": "Comparte el plan con los vecinos e inscribe a quienes quieran un letrero en su jardín.", "k235": "Visitas por las cuadras de Hollis Park", "k236": "Misma sala, misma pizza, nueva lista de llamadas. Trae a un amigo y dupliquen las llamadas.", "k237": "ene", "k238": "Punto de encuentro del autobús escolar a pie de Marlowe Street", "k239": "Cronometra los semáforos, cuenta los autos y marca las rampas faltantes.", "k240": "Recorrido de revisión en Marlowe Street", "k241": "Jue", "k242": "Cafetería de Bayview Middle School", "k243": "Maestros y padres hablan del camino a la escuela y de lo que cambia un voto Sí.", "k244": "Asamblea de padres y maestros", "k245": "feb", "k246": "Salón Sindical, Dockside", "k247": "Recoge un paquete y una ruta. Cada turno dura dos horas o más, a tu elección.", "k248": "Inicio de visitas del último fin de semana", "k249": "Dom", "k250": "Recuerda a los simpatizantes que la votación es el martes y dónde está su casilla.", "k251": "Llamadas para movilizar el voto", "k252": "Filtrar por tipo de evento", "k253": "Aún no hay reuniones en casa programadas.", "k254": "¿Quieres organizar una? Inscríbete abajo y te ayudamos a planearla.", "k255": "Cerrar", "k256": "Personas incluyéndote", "k257": "Confirmar", "k258": "Estás en la lista.", "k259": "Un recordatorio sale el día anterior. En esta demostración no se envió nada.", "k260": "21 nov: Recorrido de revisión en Delaney Street", "k261": "24 nov: Llamadas del martes", "k262": "5 dic: Visitas casa por casa en Bayview", "k263": "9 dic: Asamblea pública sobre la Medida 12", "k264": "12 dic: Visitas por las cuadras de Hollis Park", "k265": "15 dic: Llamadas del martes", "k266": "9 ene: Recorrido de revisión en Marlowe Street", "k267": "14 ene: Asamblea de padres y maestros", "k268": "6 feb: Inicio de visitas del último fin de semana", "k269": "7 feb: Llamadas para movilizar el voto", "k270": "Inscríbete como voluntario", "k271": "Elige un turno y te enviamos los detalles. Podemos organizar transporte y cuidado infantil.", "k272": "Turno", "k273": "Elige un turno", "k274": "Teléfono", "k275": "opcional", "k276": "Inscribirme al turno", "k277": "Quedaste inscrito.", "k278": "Un coordinador confirmará por correo. En esta demostración no se envió nada.", "k279": "¿No puedes ir? Dona", "k280": "Ven a un turno. Camina una esquina, haz una llamada o pregunta al ingeniero.", "k281": "Eventos | Sí a la 12", "k282": "Visitas, llamadas, asambleas y recorridos por la Medida 12. Confirma asistencia y añade eventos a tu calendario.", "k283": "Agrega tu nombre y compártelo con cinco personas. Así gana la Medida 12.", "k284": "Tu kit para compartir", "k285": "Escribe a un vecino", "k286": "Hola, soy yo. Me comprometí a votar Sí a la 12 el 9 de febrero. Paga cruces seguros cerca de las escuelas de nuestros hijos. ¿Puedo contar contigo?", "k287": "Copiar", "k288": "Recordatorio: la Medida 12 está en la boleta el 9 de febrero. Sí significa cruces y aceras más seguros cerca de cada escuela.", "k289": "¿Libre el sábado? Caminaremos los cruces más peligrosos cerca de Delaney Elementary a las 10. Ven y mira por qué importa la 12.", "k290": "Públicalo", "k291": "Vota Sí a la 12 el 9 de febrero. Cruces seguros. Zonas escolares más lentas. Aceras que funcionan. #SiALa12", "k292": "Cada mañana escolar, los niños de Port Ellery cruzan calles sin semáforo ni cruce marcado. La Medida 12 lo cambia. Yo me comprometí con el Sí. ¿Y tú?", "k293": "Acabo de firmar el compromiso Sí a la 12. Toma diez segundos y ayuda a que los niños caminen seguros a la escuela. #SiALa12", "k294": "Copiar enlace", "k295": "Compartir", "k296": "Pide un letrero para tu jardín", "k297": "Dirección", "k298": "Tipo de letrero", "k299": "Letrero de jardín, 24 por 18 pulgadas", "k300": "Póster de ventana, 11 por 17 pulgadas", "k301": "Pedir letrero", "k302": "Solicitud recibida.", "k303": "Un voluntario lo entregará en una semana. En esta demostración no se envió nada.", "k304": "Los letreros necesitan estacas. Las campañas también.", "k305": "Compromete tu voto", "k306": "Firma el compromiso y luego pásalo.", "k307": "Compromete tu voto | Sí a la 12", "k308": "Firma el compromiso Sí a la 12, copia mensajes y publicaciones para compartir y pide un letrero. Todo funciona en tu navegador.", "k309": "Monto", "k310": "Tus datos", "k311": "Pago de demostración", "k312": "Listo", "k313": "Das", "k314": "una vez", "k315": "cada mes", "k316": "Elige un monto", "k317": "Monto en dólares", "k318": "Monto personalizado en dólares", "k319": "Otro", "k320": "Frecuencia", "k321": "Una vez", "k322": "Mensual", "k323": "Continuar", "k324": "Nombre", "k325": "Apellido", "k326": "Tus datos", "k327": "Empleador", "k328": "Ocupación", "k329": "Soy ciudadano o residente permanente de EE. UU. y este es mi propio dinero.", "k330": "Atrás", "k331": "Revisa tu aporte", "k332": "Demostración: no se cobra ningún pago real. En este sitio no se recopilan datos de tarjeta.", "k333": "Nombre", "k334": "Una campaña real conectaría aquí un procesador de pagos.", "k335": "Confirmar donación de demostración", "k336": "Esto fue una demostración, así que no se movió dinero. Un recibo real llegaría por correo.", "k337": "Confirmación de demostración", "k338": "No se envió ni guardó nada.", "k339": "Empezar de nuevo", "k340": "Progreso", "k341": "Lo que hace un aporte", "k342": "imprime 60 letreros (ejemplo)", "k343": "cubre un mes de pizza y capacitación para llamadas (ejemplo)", "k344": "financia una carta a 2,400 hogares (ejemplo)", "k345": "Otras formas de ayudar", "k346": "Ser voluntario", "k347": "Toma un turno de dos horas. Camina una esquina, visita unas casas o haz llamadas.", "k348": "Ver eventos", "k349": "Comprometerte", "k350": "Agrega tu nombre y envía el kit a cinco vecinos.", "k351": "Reglas de aportes", "k352": "Los aportes no son deducibles de impuestos. Debes aportar con fondos propios y ser elegible según la ley local. Los aportes corporativos pueden tener límites. Este sitio conceptual no recibe pagos reales.", "k353": "Da lo que puedas. Los aportes pagan letreros, cartas y capacitación de voluntarios.", "k354": "Donar | Sí a la 12", "k355": "Dona a la campaña Sí a la 12. Este es un flujo de demostración: no se cobra ningún pago real y no se guarda nada.", "k356": "Qué recopilamos", "k357": "Nada. Los formularios de este sitio muestran cómo funcionaría uno real y luego descartan lo que escribiste.", "k358": "Qué se queda en tu navegador", "k359": "Tu idioma, tu elección de modo claro u oscuro y el contador de ejemplo se guardan en el almacenamiento de tu navegador. Puedes borrarlos en la configuración del navegador.", "k360": "Archivos de terceros", "k361": "Las fuentes se cargan desde Google Fonts y los iconos desde unpkg. Esos servicios pueden recibir tu dirección IP al entregar los archivos.", "k362": "Una campaña real", "k363": "Una versión real de este sitio publicaría una política completa sobre correo, mensajes de texto, donaciones y uso compartido de datos.", "k364": "Este es un sitio conceptual. Nada de lo que escribes sale de tu navegador.", "k365": "Privacidad | Sí a la 12", "k366": "Cómo este sitio conceptual maneja tu información: no envía ni recopila nada.", "k367": "Nuestra meta", "k368": "Diseñamos según WCAG 2.2 nivel AA: contraste legible en modo claro y oscuro, foco de teclado visible y botones de al menos 44 píxeles de alto.", "k369": "Qué incluye", "k370": "Enlace para saltar al contenido, formularios con etiquetas y errores bajo cada campo, menús, diálogos y acordeones operables con teclado, y texto completo en inglés y español.", "k371": "El movimiento respeta la configuración de tu sistema. Con movimiento reducido, las franjas, el contador y el diagrama aparecen sin animación.", "k372": "Cuéntanos de una barrera", "k373": "Este es un sitio conceptual, así que no hay un buzón activo. Una campaña real incluiría aquí un correo y un teléfono y respondería en dos días hábiles.", "k374": "Todos deben poder leer sobre la Medida 12, comprometerse y votar.", "k375": "Accesibilidad | Sí a la 12", "k376": "Compromisos y funciones de accesibilidad del sitio conceptual Sí a la 12.", "js_counted": "Compromiso contado. Eres el número", "js_copy": "Copiar", "js_copied": "Copiado", "js_once": "Una vez", "js_monthly": "Mensual", "js_e_req": "Este campo es obligatorio.", "js_e_email": "Ingresa un correo válido.", "js_e_zip": "Ingresa un código postal de 5 dígitos.", "js_e_amount": "Elige o ingresa un monto.", "js_e_cap": "Las donaciones de demostración tienen un límite de $5,000.", "js_ics_desc": "Evento de voluntarios de Sí a la 12. Concepto ficticio.", "js_v_none": "Sin cruce marcado: el autobús sigue y los peatones esperan un hueco.", "js_v_cw": "Con cruce marcado: el autobús reduce, pero los peatones aún esperan un hueco.", "js_v_sig": "Con semáforo: el autobús se detiene en la línea y el peatón cruza."}};

