      $("[data-b-dist]").style.transform = "scaleX(" + (c.d / 44) + ")";
      $("[data-b-speed]").style.transform = "scaleX(" + (c.s / 31.4) + ")";
      $("[data-b-risk]").style.transform = "scaleX(" + (c.r / 100) + ")";
      verdict.textContent = tr(state.sig ? "js_v_sig" : state.cw ? "js_v_cw" : "js_v_none");
