      var pedStart = state.sig ? approach + 200 : approach + (state.cw ? 600 : 900);
      var span = (state.curb ? 22 - 5.6 : 22) * unit + 2.2 * unit;
      var fromX = state.curb ? 2.8 * unit : 0;
